DAY = 5

L0 = [
  {'part': 'read'},
  "Replication is easy to switch on and hard to operate. The hard parts are all about **lag** (how far behind a replica is) and **failover** (deciding that the leader is dead, promoting someone else, and making sure the old leader does not come back and keep accepting writes).",
  {'h': 'Where lag bites, with fixes'},
  {'table': {'head': ['Symptom', 'Cause', 'Fix'], 'rows': [
    ['User edits profile, page shows the old name', 'Read went to a replica that has not received the write', 'Read your own data from the leader for a few seconds after you write (a cookie or session flag)'],
    ['A list shows a comment, then on refresh it disappears', 'Consecutive reads hit replicas at different lag', 'Pin a user to one replica (monotonic reads)'],
    ['A reply appears before the message it answers', 'Causally related writes arrive out of order', 'Read both from the same partition/leader, or carry version info'],
    ['Background job reads stale data right after enqueue', 'Job reads from a replica', 'Pass the data, or a minimum version, with the job']]}},
  {'h': 'Failover, step by step'},
  {'ol': ['**Detect.** Usually a missed heartbeat for some seconds. Too short a timeout causes failovers on a hiccup; too long means minutes of no writes.', '**Choose.** Promote the most up-to-date replica. With asynchronous replication it may still lack the last writes, which are lost or must be reconciled.', '**Reconfigure.** Point clients and other replicas at the new leader (DNS, proxy, or a service registry).', '**Fence the old leader.** If it is only partitioned, not dead, it may still accept writes. Fencing (revoking its access, or a token the storage checks) prevents two leaders, known as split brain.']},
  "Practise failover regularly. A failover path that is only exercised during a real outage will contain surprises.",
  {'h': 'Backups are not replication'},
  "A replica copies mistakes instantly: `DELETE FROM users` runs on every replica within milliseconds. Backups (and point-in-time recovery from the WAL archive) protect against mistakes and corruption; replication protects against machine loss. You need both, and you only know backups work if you restore them regularly.",
  {'part': 'real'},
  {'case': {'who': 'GitHub', 'when': 'October 21, 2018', 'title': '43 seconds of network partition, 24 hours of degraded service',
    'body': ["During maintenance, the link between GitHub's US East Coast network hub and its primary East Coast data center was lost for 43 seconds. Orchestrator, their MySQL failover tool, promoted primaries on the West Coast. But the East Coast primaries had accepted a few seconds of writes that had not replicated, so after the network healed the two sides held different data, and the application now had to talk to databases across the continent.",
      "GitHub chose consistency over availability: rather than serve possibly wrong data, they degraded service while restoring from backups, replaying writes and reconciling, which took 24 hours and 11 minutes. No user data was lost."],
    'lesson': 'Automatic cross-region failover can create two diverged copies. Know what your failover tool will do in a partition, and whether your application can live with the result.',
    'src': [['October 21 post-incident analysis (GitHub)', 'https://github.blog/2018-10-30-oct21-post-incident-analysis/']]}},
  {'case': {'who': 'GitLab', 'when': 'January 31, 2017', 'title': 'Replication broke, a fix went to the wrong server, and backups did not work',
    'body': ["While fighting replication lag caused by a spam attack, an engineer tried to reset the replica by deleting its data directory, but ran the command on the primary. Around 300 GB of production data was removed. When the team turned to backups, several of the backup methods turned out not to be working, and they restored from a staging snapshot about six hours old. GitLab live-streamed the recovery and published a very open postmortem."],
    'lesson': 'Replication does not protect against human error. Make destructive commands hard to run on the wrong host, and test restores, not just backups.',
    'src': [['Postmortem of database outage of January 31 (GitLab)', 'https://about.gitlab.com/blog/2017/02/10/postmortem-of-database-outage-of-january-31/']]}},
  {'part': 'apply'},
  {'code': "// Read-your-writes: send a user's reads to the primary for 5 seconds after they write\nconst STICKY_MS = 5000;\napp.use((req, res, next) => {\n  const until = Number(req.signedCookies.primaryUntil || 0);\n  req.db = (req.method !== 'GET' || Date.now() < until) ? primary : replica;\n  if (req.method !== 'GET') {\n    res.cookie('primaryUntil', String(Date.now() + STICKY_MS), { signed: true, httpOnly: true });\n  }\n  next();\n});", 'lang': 'js', 'cap': 'A simple read-your-writes router'},
  {'code': "-- PostgreSQL, on the primary: how far behind is each replica?\nSELECT application_name, state,\n       pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS bytes_behind,\n       replay_lag\nFROM pg_stat_replication;\n\n-- On a replica: seconds since the last replayed transaction\nSELECT now() - pg_last_xact_replay_timestamp() AS lag;", 'lang': 'sql', 'cap': 'Monitor replication lag'},
  {'check': ['Alert on replication lag, in seconds and bytes.', 'Route reads after a write to the leader (read-your-writes) where users would notice.', 'Know your failover mechanism, its detection timeout and how it fences the old leader.', 'Run a failover drill on a schedule.', 'Keep backups plus WAL archiving for point-in-time recovery.', 'Restore a backup into a scratch environment at least monthly and check the data.']},
]

L1 = [
  {'part': 'read'},
  "Sharding is a one-way door: once data is spread across machines, queries that cross shards become expensive forever. So the shard key deserves more thought than almost any other decision. A good test: for your top queries, how many shards does each one touch? Ideally one.",
  {'h': 'Choosing a key, worked through'},
  {'table': {'head': ['Product', 'Candidate key', 'Verdict'], 'rows': [
    ['B2B SaaS (workspaces)', 'workspace_id', 'Great: almost every query is inside one workspace, and data for a customer stays together. Watch the few huge customers.'],
    ['Social network posts', 'post_id', 'Even spread, but "all posts by user X" touches every shard. author_id keeps a user’s posts together.'],
    ['Messages', 'channel_id (+ time bucket)', 'Reads are by channel and recent first; buckets stop giant channels growing one partition forever.'],
    ['Orders', 'created_at (range)', 'Bad: today’s shard takes all the writes. Use customer_id or a hash instead.']]}},
  {'h': 'Logical shards: the trick that makes resharding bearable'},
  "Instead of sharding directly onto N machines, split the data into many more **logical shards** (say 1,024 or 480) and map several logical shards to each physical database. To add capacity, move whole logical shards to new machines; the key-to-logical-shard function never changes, only the small mapping table does. Moving a logical shard is a well-defined job: copy, catch up with replication, switch, verify.",
  {'h': 'What you lose, and the usual workarounds'},
  {'ul': ['**Cross-shard joins:** denormalise, or build a read model (search index, warehouse) fed by events.', '**Global unique constraints** (unique username): a separate lookup table sharded by that value, written in the same flow.', '**Auto-increment IDs:** need a distributed ID scheme (see unique ID generation on Day 8).', '**Transactions across shards:** avoid by design, or use sagas.']},
  {'part': 'real'},
  {'case': {'who': 'Notion', 'when': '2021 and 2023', 'title': '480 logical shards, from 32 to 96 machines',
    'body': ["Notion sharded its PostgreSQL data by workspace, so a workspace's blocks all live together. They chose 480 logical shards (as separate Postgres schemas) spread over 32 physical databases, because 480 divides evenly by many numbers and allows growing the fleet in steps. The routing from workspace ID to shard lives in the application. In 2023 they re-sharded onto 96 machines without changing the logical shard count, using Postgres logical replication to copy data and switching traffic gradually."],
    'lesson': 'Pick a shard key that matches ownership of the data, and use many logical shards so future growth is a data move, not a redesign.',
    'src': [['Herding elephants: Lessons learned from sharding Postgres at Notion', 'https://www.notion.com/blog/sharding-postgres-at-notion'], ['The Great Re-shard', 'https://www.notion.com/blog/the-great-re-shard']]}},
  {'case': {'who': 'Instagram', 'when': '2012', 'title': 'Thousands of logical shards and IDs that know their shard',
    'body': ["Instagram described sharding PostgreSQL into several thousand logical shards (schemas) mapped onto far fewer physical servers. Each object's 64-bit ID contains a timestamp, the logical shard ID and a sequence number, generated inside the database. So the ID alone tells you where the object lives, and IDs sort roughly by time."],
    'lesson': 'Encoding the shard in the ID removes a lookup on every read and makes the system easier to reason about.',
    'src': [['Sharding & IDs at Instagram', 'https://instagram-engineering.com/sharding-ids-at-instagram-1cf5a71e5a5c']]}},
  {'part': 'apply'},
  {'code': "// Consistent hashing with virtual nodes: how many keys move when a server joins?\nfunction hash(s) { let h = 2166136261; for (const c of s) h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0; return h; }\nfunction ring(servers, vnodes = 100) {\n  return servers.flatMap(s => Array.from({ length: vnodes }, (_, i) => [hash(s + '#' + i), s])).sort((a, b) => a[0] - b[0]);\n}\nfunction owner(r, key) { const h = hash(key); return (r.find(([p]) => p >= h) || r[0])[1]; }\n\nconst keys = Array.from({ length: 20000 }, (_, i) => 'user:' + i);\nconst before = ring(['db1', 'db2', 'db3', 'db4']), after = ring(['db1', 'db2', 'db3', 'db4', 'db5']);\nconst moved = keys.filter(k => owner(before, k) !== owner(after, k)).length;\nconsole.log('consistent hashing moved', (moved / keys.length * 100).toFixed(1) + '% of keys'); // close to 1/5 (20 to 27% depending on the hash)\nconst modMoved = keys.filter(k => hash(k) % 4 !== hash(k) % 5).length;\nconsole.log('hash mod N moved', (modMoved / keys.length * 100).toFixed(1) + '% of keys');       // about 80%", 'lang': 'js', 'cap': 'Run it: about 1/N of keys move instead of most of them'},
  {'code': "// Logical shards: the key->shard function never changes; only the shard->host map does\nconst LOGICAL = 480;\nconst shardOf = workspaceId => hash(String(workspaceId)) % LOGICAL;\nconst hostOf = shard => shardMap[shard];      // e.g. loaded from config: { 0: 'pg-01', 1: 'pg-01', ... }\nconst dbFor = workspaceId => pools[hostOf(shardOf(workspaceId))];", 'lang': 'js', 'cap': 'Routing with logical shards'},
  {'check': ['Exhaust simpler options first: indexes, caching, read replicas, a bigger machine.', 'List your top queries and check how many shards each would touch for each candidate key.', 'Prefer a key that matches data ownership (tenant, user, channel).', 'Use many logical shards mapped onto fewer physical hosts.', 'Plan IDs, unique constraints and cross-shard reporting before migrating.', 'Watch per-shard load to catch hot shards early.']},
]

L2 = [
  {'part': 'read'},
  "CAP and PACELC become practical once you apply them per feature. For each piece of data ask two questions: if replicas cannot talk to each other, do I prefer to **refuse** (consistency) or to **answer, possibly stale** (availability)? And in normal times, is it worth extra **latency** to always read the latest value?",
  {'h': 'Quorums: tuning the trade-off with numbers'},
  "In leaderless stores (Dynamo-style, Cassandra) each value is stored on N replicas. A write waits for W acknowledgements, a read asks R replicas and takes the newest. If **R + W > N**, every read overlaps at least one replica that has the latest write.",
  {'table': {'head': ['N, W, R', 'R + W > N?', 'Behaviour'], 'rows': [
    ['3, 2, 2', 'yes', 'Balanced: tolerates one slow or failed replica for both reads and writes'],
    ['3, 3, 1', 'yes', 'Fast reads, but writes fail if any replica is down'],
    ['3, 1, 3', 'yes', 'Fast writes, slow reads'],
    ['3, 1, 1', 'no', 'Fastest and most available; reads can be stale']]}},
  "Even R + W > N is not full linearizability (concurrent writes, sloppy quorums and read repair have edge cases), but it is the main dial these systems give you.",
  {'h': 'Per-feature decisions in one product'},
  {'table': {'head': ['Data', 'Under partition', 'Why'], 'rows': [
    ['Account balance', 'Refuse (CP)', 'Showing or spending money that is not there is worse than an error'],
    ['Seat booking', 'Refuse or hold (CP)', 'Double-selling has a real cost'],
    ['Shopping cart', 'Accept (AP)', 'Losing an add-to-cart costs a sale; merging carts later is acceptable'],
    ['Like counts, view counts', 'Accept (AP)', 'Slightly wrong numbers are harmless'],
    ['Username uniqueness', 'Refuse (CP)', 'Two users with one name is a lasting problem']]}},
  {'part': 'real'},
  {'case': {'who': 'Amazon', 'when': '2007', 'title': 'Dynamo: a shopping cart that is always writable',
    'body': ["Amazon designed Dynamo so that 'add to cart' would succeed even during failures and network partitions, because rejecting it loses sales. Replicas can therefore diverge, and divergent versions of a cart (tracked with vector clocks) are merged when read. The paper is honest about the trade-off: in rare cases an item that was removed can reappear after a merge."],
    'lesson': 'Availability is a business decision. Pick AP where a merge is acceptable and the cost of refusing is high.',
    'src': [['Dynamo: Amazon’s Highly Available Key-value Store', 'https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf']]}},
  {'case': {'who': 'Google', 'when': '2012 and 2017', 'title': 'Spanner: strong consistency across the planet, paid in latency',
    'body': ["Spanner offers externally consistent transactions across data centers worldwide. It uses TrueTime, clocks with a known uncertainty bound from GPS and atomic clocks, and waits out that uncertainty before committing, plus Paxos replication. Eric Brewer, who formulated CAP, later wrote that Spanner is technically a CP system but, thanks to Google's private network, partitions are rare enough that it behaves as highly available in practice."],
    'lesson': 'Strong consistency at global scale is possible, but you pay in write latency and specialised infrastructure (PACELC: else, consistency over latency).',
    'src': [['Spanner, TrueTime and the CAP Theorem (Google Research)', 'https://research.google/pubs/pub45855/']]}},
  {'part': 'apply'},
  {'code': "// Quorum simulator: probability a read misses the latest write, for given N, W, R\nfunction pick(N, k) { const a = [...Array(N).keys()]; for (let i = N - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a.slice(0, k); }\nfunction staleRate(N, W, R, trials = 100000) {\n  let stale = 0;\n  for (let t = 0; t < trials; t++) {\n    const wrote = new Set(pick(N, W));                      // replicas that acked the write\n    const read = pick(N, R);\n    if (!read.some(n => wrote.has(n))) stale++;\n  }\n  return (stale / trials * 100).toFixed(1) + '%';\n}\nconsole.log('N3 W2 R2', staleRate(3, 2, 2)); // 0.0%\nconsole.log('N3 W1 R1', staleRate(3, 1, 1)); // about 66.7% (if the other replicas have not caught up yet)", 'lang': 'js', 'cap': 'R + W > N guarantees overlap'},
  {'check': ['List each kind of data and choose CP or AP for it, with a one-line reason.', 'For AP data, decide how conflicts merge (or that last write wins is acceptable).', 'For CP data, decide what users see when the system refuses (an error, a retry, a queue).', 'If you use a quorum store, set R and W per query type deliberately.', 'Measure replication lag so "eventual" has a number attached.', 'Write the read-your-writes requirements down; they are the most noticeable to users.']},
]

L3 = [
  {'part': 'read'},
  "Conflicts are not an edge case in offline-first apps, multi-region writes or real-time collaboration; they are the normal case. The design question is which merge rule is *correct for this data*. A counter, a set of tags, a document title and a bank balance each need a different answer.",
  {'h': 'Why wall-clock last-write-wins loses data'},
  "Server clocks drift by milliseconds or more, and can jump backward when synchronised. If replica A's clock is 50 ms ahead, its writes win every conflict within that window even when they happened earlier. Logical clocks fix ordering without trusting time: a **Lamport clock** gives a total order consistent with causality; **vector clocks** additionally tell you when two writes were truly concurrent, so you can merge or ask the user instead of silently dropping one.",
  {'h': 'CRDTs you can use today'},
  {'table': {'head': ['CRDT', 'Merge rule', 'Good for'], 'rows': [
    ['G-Counter / PN-Counter', 'Each replica counts its own increments; total is the sum', 'Likes, views, votes'],
    ['OR-Set (observed-remove set)', 'Adds win over concurrent removes of unseen adds', 'Tags, members, cart items'],
    ['LWW-Register', 'Highest (logical time, replica ID) wins', 'A single field where losing a concurrent edit is fine'],
    ['Sequence CRDTs (RGA, Yjs, Automerge)', 'Characters get stable IDs; concurrent inserts are ordered deterministically', 'Collaborative text and lists']]}},
  {'part': 'real'},
  {'case': {'who': 'Figma', 'when': '2019', 'title': 'CRDT ideas, simplified by a central server',
    'body': ["Figma studied operational transforms and CRDTs for its multiplayer editing and chose something simpler. A document is a tree of objects, each with properties. The server keeps the latest value for each property of each object, so two people editing different properties never conflict, and when they edit the same property the last value to reach the server wins, like a last-writer-wins register but ordered by the server rather than by timestamps."],
    'lesson': 'With a central server you can borrow CRDT ideas without their full complexity. Choose the merge granularity (per property) to make conflicts rare.',
    'src': [['How Figma’s multiplayer technology works', 'https://www.figma.com/blog/how-figmas-multiplayer-technology-works/']]}},
  {'case': {'who': 'Cloudflare', 'when': 'January 1, 2017', 'title': 'A leap second made time go backward',
    'body': ["When a leap second was added at the end of 2016, code in Cloudflare's DNS software computed a time difference that came out negative, because it assumed time never goes backward. The negative value caused a panic, and some DNS lookups failed for customers using CNAME records until a fix rolled out over the following hours."],
    'lesson': 'Wall clocks can jump. Use monotonic clocks for durations and logical clocks for ordering events.',
    'src': [['How and why the leap second affected Cloudflare DNS', 'https://blog.cloudflare.com/how-and-why-the-leap-second-affected-cloudflare-dns/']]}},
  {'part': 'apply'},
  {'code': "// G-Counter: each replica increments its own slot; merge takes the max per slot\nconst inc = (c, id, n = 1) => ({ ...c, [id]: (c[id] || 0) + n });\nconst merge = (a, b) => { const m = { ...a }; for (const k in b) m[k] = Math.max(m[k] || 0, b[k]); return m; };\nconst value = c => Object.values(c).reduce((x, y) => x + y, 0);\n\nlet phone = inc({}, 'phone', 3), laptop = inc({}, 'laptop', 2);   // offline likes on two devices\nconst a = merge(phone, laptop), b = merge(laptop, phone);\nconsole.log(value(a), value(b), value(merge(a, a)));                // 5 5 5: order and repeats do not matter\n\n// Vector clocks: did two writes happen concurrently?\nconst cmp = (x, y) => {\n  const keys = new Set([...Object.keys(x), ...Object.keys(y)]);\n  let le = true, ge = true;\n  for (const k of keys) { if ((x[k] || 0) > (y[k] || 0)) le = false; if ((x[k] || 0) < (y[k] || 0)) ge = false; }\n  return le && ge ? 'equal' : le ? 'before' : ge ? 'after' : 'concurrent';\n};\nconsole.log(cmp({ A: 2, B: 1 }, { A: 2, B: 2 })); // before\nconsole.log(cmp({ A: 3, B: 1 }, { A: 2, B: 2 })); // concurrent: merge or ask the user", 'lang': 'js', 'cap': 'A CRDT counter and vector clock comparison'},
  {'check': ['List data that can be written in two places at once (devices, regions, collaborators).', 'Pick a merge rule per field: CRDT, last-writer-wins, or route to a single leader.', 'Never order events by comparing wall-clock times from different machines.', 'Use a monotonic clock for timeouts and durations.', 'For collaborative text, use a proven library (Yjs, Automerge) rather than writing your own.', 'Test conflicts: edit the same item offline on two clients, reconnect, check the result.']},
]

L4 = [
  {'part': 'read'},
  "Most 'distributed transactions' in product code are workflows: create an order, reserve stock, charge a card, schedule shipping. Each step lives in a different service or system, and any step can fail or time out. The design goal is that every workflow ends in a sensible state, either completed or cleanly undone, even if processes crash halfway.",
  {'h': 'Orchestration vs choreography'},
  {'table': {'head': ['', 'Orchestration', 'Choreography'], 'rows': [
    ['How', 'A coordinator calls each step and decides what is next', 'Services react to each other’s events'],
    ['Visibility', 'The whole flow is in one place', 'The flow is spread across services'],
    ['Coupling', 'Coordinator knows every step', 'Services only know events'],
    ['Good for', 'Business-critical flows with many steps and compensations', 'Simple reactions (send email when order placed)']]}},
  {'h': 'Designing compensations'},
  "A compensation is not a rollback; the first step really happened and others may have seen it. 'Refund the charge' is a new action, not an erased charge. Some steps cannot be compensated (an email was sent), so put them last, after everything that might fail. Make every step and every compensation idempotent, because the coordinator will retry them.",
  {'h': 'Durable execution'},
  "The coordinator must survive crashes: if it dies after charging the card, a restarted coordinator must know to continue with shipping, not charge again. Workflow engines (Temporal, AWS Step Functions, Netflix Conductor) store each step's result durably and resume from the last completed step, which removes a lot of hand-written state machines.",
  {'part': 'real'},
  {'case': {'who': 'Hector Garcia-Molina and Kenneth Salem', 'when': '1987', 'title': 'The original sagas paper',
    'body': ["The term saga comes from a 1987 paper about long-lived transactions in databases: transactions that run for a long time and would hold locks for too long if executed as one unit. The proposal was to split them into a sequence of smaller transactions, each paired with a compensating transaction, so that the system either completes all of them or runs compensations for those that committed."],
    'lesson': 'Sagas are an old, proven idea. Microservices made them common again because each service owns its own database.',
    'src': [['Sagas (Garcia-Molina and Salem, 1987)', 'https://www.cs.cornell.edu/andru/cs711/2002fa/reading/sagas.pdf']]}},
  {'case': {'who': 'Netflix', 'when': '2016', 'title': 'Conductor: orchestration for microservice workflows',
    'body': ["Netflix built Conductor to orchestrate workflows across microservices, such as content ingestion and encoding pipelines, after choreography through events made flows hard to track and change. Workflows are defined as a series of tasks; the engine tracks state, retries, timeouts and failures, and gives visibility into where each workflow instance is."],
    'lesson': 'Once flows have many steps and failure paths, a central orchestrator with durable state is easier to operate than a web of events.',
    'src': [['Netflix Conductor: A microservices orchestrator', 'https://netflixtechblog.com/netflix-conductor-a-microservices-orchestrator-2e8d4771bf40']]}},
  {'part': 'apply'},
  {'code': "// A minimal saga orchestrator: run steps in order; on failure, compensate completed steps in reverse\nasync function runSaga(steps, ctx) {\n  const done = [];\n  for (const step of steps) {\n    try { await step.run(ctx); done.push(step); }\n    catch (err) {\n      for (const s of done.reverse()) await s.compensate(ctx);  // must be idempotent\n      return { ok: false, failedAt: step.name, reason: err.message };\n    }\n  }\n  return { ok: true };\n}\n\nconst log = [];\nconst order = [\n  { name: 'reserveStock', run: async () => log.push('reserved'), compensate: async () => log.push('released') },\n  { name: 'chargeCard',   run: async () => log.push('charged'),  compensate: async () => log.push('refunded') },\n  { name: 'bookCourier',  run: async () => { throw new Error('no couriers'); }, compensate: async () => {} },\n  { name: 'sendEmail',    run: async () => log.push('emailed'),  compensate: async () => {} },  // irreversible: last\n];\nrunSaga(order, {}).then(r => console.log(r, log));\n// { ok: false, failedAt: 'bookCourier', ... } [ 'reserved', 'charged', 'refunded', 'released' ]", 'lang': 'js', 'cap': 'Run it to see compensations happen in reverse order'},
  {'check': ['Draw each multi-service workflow as steps with a compensation for each.', 'Put irreversible steps (emails, shipping) last.', 'Make every step and compensation idempotent, keyed by the workflow ID.', 'Store workflow progress durably, or use a workflow engine.', 'Give every step a timeout and decide what a timeout means (retry, or compensate).', 'Build a view that shows stuck or failed workflows so someone can act on them.']},
]

LESSONS = [L0, L1, L2, L3, L4]
